"""Open Studio runtime additions for the bundled embeddable Python."""

import os
import sys


def _add_open_studio_packages():
    package_dir = os.environ.get("OPEN_STUDIO_PYTHON_PACKAGES", "").strip()
    if not package_dir:
        return

    package_dir = os.path.abspath(os.path.expandvars(os.path.expanduser(package_dir)))
    if os.path.isdir(package_dir) and package_dir not in sys.path:
        # User-installed packages should take precedence over the bundled set.
        sys.path.insert(0, package_dir)


_add_open_studio_packages()
